#!/usr/bin/env node
/**
 * `npm run coverage:matrix`
 *
 * How much of what the structural detector finds does the lexical rule also find?
 *
 * ## Why this is the question
 *
 * This started from a sentence the project had been writing: that `chat.unsolicited_advice` is a
 * **lexical proxy** for the action-plan behaviour, a cheap stand-in the structural features would
 * eventually replace. The measurement says otherwise, so the sentence is gone.
 *
 * | Corpus | lexical fires | structural plans | both |
 * | --- | --- | --- | --- |
 * | calibration bank | 1 | 69 | 1 |
 * | blind set | 0 | 72 | 0 |
 * | HelpSteer3 (Chinese) | 58 | 210 | 13 |
 *
 * On HelpSteer3 the rule fires 58 times and **45 of those replies are not plan-shaped at all**. Two
 * detectors that overlap on 13 of 268 firings are not a proxy and its target; they are two different
 * phenomena that intersect. Until those 45 are read by hand, nothing about the rule changes — not
 * its name, not its weight, not its description, and no claim that it detects uninvited solution
 * mode. What a report may say is what it actually does: it fires on five phrases in a reply whose
 * user turn did not ask for advice.
 *
 * | Cell | Meaning |
 * | --- | --- |
 * | both | The lexical rule fires and the reply is plan-shaped |
 * | lexical only | The rule fires on something that is not a plan by structure |
 * | structural only | A plan the rule cannot see, which is the gap the features exist for |
 * | neither | No plan, no marker |
 *
 * Reported per permission state, because a plan under `HIGH` is a good answer and the interesting
 * cell is a plan under `LOW`.
 *
 * ## What it does not do
 *
 * It does not propose removing the lexical rule, renaming it, reweighting it or replacing it. The
 * two run in parallel until the lexical-only replies have been read, and this tool exists to make
 * that reading possible rather than to pre-empt it.
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { hasAdviceMarker, solutionFeatures } from './solution-mode.js';
import { permissionOf } from './permission.js';
import type { Permission } from './permission.js';
import { BLIND_PROMPTS, SOLUTION_PROMPTS } from './solution-probes.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..');
const OUT = path.join(HERE, 'COVERAGE_MATRIX.md');
const HELPSTEER = path.join(ROOT, '.external-corpora', 'helpsteer3');

const RULE = 'chat.unsolicited_advice';
const PERMISSIONS: readonly Permission[] = ['LOW', 'MEDIUM', 'HIGH', 'UNCERTAIN'];

interface Case {
  readonly text: string;
  readonly permission: Permission;
  /** Whether `chat.unsolicited_advice` fired, where a scan is available. */
  readonly ruleFired?: boolean;
}

interface Cell {
  both: number;
  lexicalOnly: number;
  structuralOnly: number;
  neither: number;
}

function emptyCell(): Cell {
  return { both: 0, lexicalOnly: 0, structuralOnly: 0, neither: 0 };
}

function classify(entry: Case, into: Cell): void {
  const lexical = entry.ruleFired ?? hasAdviceMarker(entry.text);
  const structural = solutionFeatures(entry.text).isPlan;
  if (lexical && structural) into.both += 1;
  else if (lexical) into.lexicalOnly += 1;
  else if (structural) into.structuralOnly += 1;
  else into.neither += 1;
}

function main(): number {
  const lines: string[] = [];
  const push = (...text: string[]): void => {
    for (const line of text) lines.push(line);
  };
  const pct = (value: number, total: number): string => `${((value / Math.max(1, total)) * 100).toFixed(1)}%`;

  push(
    '# Coverage: what the lexical advice rule sees of the structural plans',
    '',
    '<!-- Generated by `npm run coverage:matrix`. Statistics only: no source text. -->',
    '',
    '`chat.unsolicited_advice` watches five phrases. The frozen action-plan features are structural.',
    'These tables measure how much of the second the first also finds.',
    '',
    '| Cell | Meaning |',
    '| --- | --- |',
    '| both | The rule fires and the reply is plan-shaped |',
    '| lexical only | The rule fires on something that is not a plan by structure |',
    '| structural only | A plan the rule cannot see |',
    '| neither | No plan, no marker |',
    '',
  );

  const batches: ReadonlyArray<{ name: string; file: string; prompts: ReadonlyArray<{ id: string; userTurn: string }> }> = [
    {
      name: 'solution-mode calibration bank',
      file: path.join(ROOT, '.external-corpora', 'solution', 'generated.jsonl'),
      prompts: SOLUTION_PROMPTS,
    },
    {
      name: 'solution-mode blind set',
      file: path.join(ROOT, '.external-corpora', 'solution-blind', 'generated.jsonl'),
      prompts: BLIND_PROMPTS,
    },
  ];

  const overall = emptyCell();
  for (const batch of batches) {
    if (!existsSync(batch.file)) continue;
    const rows = readFileSync(batch.file, 'utf8')
      .split('\n')
      .filter((line) => line.trim().length > 0)
      .map((line) => JSON.parse(line) as { id: string; text: string });
    const promptOf = new Map(batch.prompts.map((prompt) => [prompt.id, prompt]));

    const byPermission = new Map<Permission, Cell>(PERMISSIONS.map((state) => [state, emptyCell()]));
    const total = emptyCell();
    for (const row of rows) {
      const prompt = promptOf.get(row.id);
      if (prompt === undefined) continue;
      const entry: Case = { text: row.text, permission: permissionOf({ userTurn: prompt.userTurn }).permission };
      classify(entry, total);
      classify(entry, byPermission.get(entry.permission)!);
      classify(entry, overall);
    }

    const n = total.both + total.lexicalOnly + total.structuralOnly + total.neither;
    push(
      `## ${batch.name} (${n} replies)`,
      '',
      '| Permission | both | lexical only | structural only | neither |',
      '| --- | --- | --- | --- | --- |',
      ...[...byPermission.entries()].map(
        ([state, cell]) => `| \`${state}\` | ${cell.both} | ${cell.lexicalOnly} | ${cell.structuralOnly} | ${cell.neither} |`,
      ),
      `| **all** | **${total.both}** | **${total.lexicalOnly}** | **${total.structuralOnly}** | **${total.neither}** |`,
      '',
      `Of the ${total.both + total.structuralOnly} replies that are plan-shaped, the lexical rule finds ` +
        `${total.both} (${pct(total.both, total.both + total.structuralOnly)}). Of the ${total.both + total.lexicalOnly} the rule fires on, ` +
        `${total.both} are plan-shaped (${pct(total.both, total.both + total.lexicalOnly)}).`,
      '',
    );
  }

  // The external check, if the corpus is present locally.
  const external = path.join(HELPSTEER, 'preference-validation.jsonl.gz');
  const externalTrain = path.join(HELPSTEER, 'preference-train.jsonl.gz');
  const cell = emptyCell();
  let externalN = 0;
  for (const file of [external, externalTrain]) {
    if (!existsSync(file)) continue;
    const raw = gunzipSync(readFileSync(file)).toString('utf8');
    for (const line of raw.split('\n')) {
      if (line.trim().length === 0) continue;
      let row: { language?: string; context?: Array<{ role: string; content: string }>; response1?: string; response2?: string };
      try {
        row = JSON.parse(line) as typeof row;
      } catch {
        continue;
      }
      if ((row.language ?? '') !== 'chinese') continue;
      for (const text of [row.response1, row.response2]) {
        if (typeof text !== 'string' || text.trim().length === 0) continue;
        classify({ text, permission: 'UNCERTAIN' }, cell);
        externalN += 1;
      }
    }
  }
  if (externalN > 0) {
    push(
      `## HelpSteer3, Chinese rows (${externalN} responses)`,
      '',
      'Permission is not known for this corpus — the user turns are ShareGPT conversations and their',
      'intent is not labelled — so this is pooled and reported as a coverage figure only.',
      '',
      '| both | lexical only | structural only | neither |',
      '| --- | --- | --- | --- |',
      `| ${cell.both} | ${cell.lexicalOnly} | ${cell.structuralOnly} | ${cell.neither} |`,
      '',
      `Of the ${cell.both + cell.structuralOnly} plan-shaped responses, the rule finds ${cell.both} ` +
        `(${pct(cell.both, cell.both + cell.structuralOnly)}).`,
      '',
    );
  }

  push(
    '## What this says, and what it does not',
    '',
    'It says the two detectors are **not** a proxy and its target. They overlap on 13 firings out of 268,',
    'and on HelpSteer3 the rule fires 45 times on replies that are not plan-shaped at all. The honest',
    'description of `chat.unsolicited_advice` is therefore its firing condition — five phrases in a reply',
    'whose user turn did not ask for advice — and not a claim about the behaviour behind it.',
    '',
    'It does **not** say the rule should be removed, renamed or reweighted: a lexical rule is cheap,',
    'deterministic and explainable, and none of that is in question. The lexical-only replies are the',
    'ones that decide what it actually is, and reading them is the next piece of work.',
    '',
    `Generated ${new Date().toISOString()}.`,
    '',
  );

  writeFileSync(OUT, `${lines.join('\n')}\n`, 'utf8');
  process.stdout.write('\nCoverage matrix\n\n');
  process.stdout.write(
    `  everything: both ${overall.both}, lexical only ${overall.lexicalOnly}, structural only ${overall.structuralOnly}, neither ${overall.neither}\n`,
  );
  process.stdout.write(`\nWritten to ${path.relative(ROOT, OUT).split('\\').join('/')}\n`);
  return 0;
}

process.exit(main());
